// S1-Angebote in einheitliches Format überführen
const angebote = $input.first().json.value || [];

return angebote.map(ang => ({
  json: {
    angebot_id:       `ANG-S1-${ang.DocNum}`,
    angebot_typ:      erkenneTyp(ang),
    kunde_branche:    '',  // Wird aus BP-Stammdaten ergänzt wenn vorhanden
    positionen:       (ang.DocumentLines || []).map(l => ({
      bezeichnung:    l.ItemDescription || l.ItemCode || 'Unbekannt',
      kategorie:      erkennePosKategorie(l),
      menge:          l.Quantity || 1,
      einheit:        l.UoMCode || 'Stück',
      preis:          l.UnitPrice || 0
    })),
    gesamtwert_netto: ang.DocTotal || 0,
    datum:            ang.DocDate,
    status:           ang.DocumentStatus === 'O' ? 'offen' :
                      ang.DocumentStatus === 'C' ? 'gewonnen' : 'verloren',
    ersteller:        ang.SalesPersonCode || '',
    quelle:           'systemhaus-one',
    roh_daten:        ang
  }
}));

function erkenneTyp(ang) {
  const lines = (ang.DocumentLines || []).map(l =>
    (l.ItemDescription || '').toLowerCase()
  );
  if (lines.some(l => l.includes('server')))  return 'Server';
  if (lines.some(l => l.includes('switch') || l.includes('firewall') || l.includes('access point'))) return 'Netzwerk';
  if (lines.some(l => l.includes('drucker') || l.includes('printer'))) return 'Drucker';
  if (lines.some(l => l.includes('telefon') || l.includes('phone') || l.includes('headset'))) return 'Telefonie';
  if (lines.some(l => l.includes('pc') || l.includes('desktop') || l.includes('laptop') || l.includes('optiplex') || l.includes('thinkcentre'))) return 'PC-Arbeitsplatz';
  return 'Mischung';
}

function erkennePosKategorie(line) {
  const desc = (line.ItemDescription || line.ItemCode || '').toLowerCase();
  if (desc.includes('lizenz') || desc.includes('license') || desc.includes('365') || desc.includes('windows')) return 'Lizenzen';
  if (desc.includes('monitor') || desc.includes('maus') || desc.includes('tastatur') || desc.includes('keyboard') || desc.includes('docking')) return 'Peripherie';
  if (desc.includes('kabel') || desc.includes('cable') || desc.includes('adapter')) return 'Kabel & Zubehör';
  if (desc.includes('switch') || desc.includes('firewall') || desc.includes('access point') || desc.includes('router')) return 'Netzwerk';
  if (desc.includes('einrichtung') || desc.includes('service') || desc.includes('installation') || desc.includes('vor-ort')) return 'Service';
  return 'Hardware';
}

// JSON/CSV-Eingabe aus Webhook-Body oder Manual-Trigger normalisieren
const input = $input.first().json;

// Unterstützte Formate:
// 1. Array von Angeboten direkt im Body
// 2. { angebote: [...] } Wrapper-Objekt
// 3. Einzelnes Angebot-Objekt

let angebote = [];

if (Array.isArray(input.body?.angebote)) {
  angebote = input.body.angebote;
} else if (Array.isArray(input.body)) {
  angebote = input.body;
} else if (Array.isArray(input.angebote)) {
  angebote = input.angebote;
} else if (Array.isArray(input)) {
  angebote = input;
} else if (input.angebot_id || input.DocNum) {
  // Einzelnes Angebot
  angebote = [input];
} else {
  throw new Error('Kein gültiges Angebots-Format erkannt. Erwartet: Array oder Objekt mit angebote-Property.');
}

return angebote.map(a => ({ json: a }));

// Angebot als natürlichsprachlichen Text serialisieren
// (optimiert für text-embedding-3-small)
const a = $input.first().json;

// Positionen nach Kategorie gruppieren
const gruppen = {};
for (const pos of (a.positionen || [])) {
  const kat = pos.kategorie || 'Sonstige';
  if (!gruppen[kat]) gruppen[kat] = [];
  gruppen[kat].push(
    `${pos.menge}x ${pos.bezeichnung}` +
    (pos.preis ? ` (${pos.preis}€)` : '')
  );
}

// Kategorien-Reihenfolge für konsistentes Embedding
const katReihenfolge = ['Hardware', 'Peripherie', 'Kabel & Zubehör', 'Lizenzen', 'Service', 'Netzwerk', 'Sonstige'];

let text = `${a.angebot_typ || 'IT'} Angebot`;
if (a.kunde_branche) text += ` für ${a.kunde_branche}`;
text += `, ${(a.positionen || []).length} Positionen:\n`;

for (const kat of katReihenfolge) {
  if (gruppen[kat] && gruppen[kat].length > 0) {
    text += `${kat}: ${gruppen[kat].join(', ')}\n`;
  }
}

// Weitere Kategorien die nicht in der fixen Reihenfolge sind
for (const [kat, positionen] of Object.entries(gruppen)) {
  if (!katReihenfolge.includes(kat)) {
    text += `${kat}: ${positionen.join(', ')}\n`;
  }
}

if (a.gesamtwert_netto) text += `Gesamtwert: ${a.gesamtwert_netto}€ netto, `;
if (a.status)           text += `Status: ${a.status}`;

return [{
  json: {
    ...a,
    serialisierterText: text.trim()
  }
}];

// Supabase INSERT Payload bauen
const angebot   = $('Angebot serialisieren').item.json;
const embedding = $input.first().json.data[0].embedding;

const metadata = {
  angebot_id:        angebot.angebot_id,
  angebot_typ:       angebot.angebot_typ,
  kunde_branche:     angebot.kunde_branche || null,
  kategorien:        [...new Set((angebot.positionen || []).map(p => p.kategorie))],
  positionen_anzahl: (angebot.positionen || []).length,
  gesamtwert_netto:  angebot.gesamtwert_netto || null,
  datum:             angebot.datum || null,
  status:            angebot.status || null,
  ersteller:         angebot.ersteller || null,
  quelle:            angebot.quelle || 'manuell'
};

return [{
  json: {
    content:   angebot.serialisierterText,
    embedding: embedding,
    metadata:  metadata
  }
}];

// Ergebniszusammenfassung erstellen
const alleItems = $input.all();
let importiert  = 0;
let fehler      = 0;

for (const item of alleItems) {
  if (item.json.error || item.json.statusCode >= 400) {
    fehler++;
  } else {
    importiert++;
  }
}

const duplikate = parseInt($('Duplikat prüfen').all().filter(i => i.json === true).length) || 0;

return [{
  json: {
    importiert,
    fehler,
    duplikate,
    nachricht: `Ingestion abgeschlossen: ${importiert} importiert, ${duplikate} Duplikate übersprungen, ${fehler} Fehler`
  }
}];
